  TextView groupTitle=text("CHANNEL GROUPS",10);groupTitle.setLetterSpacing(.08f);groupTitle.setTextColor(TvStyle.SILVER);groupColumn.addView(groupTitle,new LayoutParams(-1,dp(26)));
  names.add("All channels");ids.add("");names.add("Favorites");ids.add("@favorites");if(app.m3uMode&&app.playlist!=null){Set<String> added=new HashSet<>();for(Playlist.Entry item:app.playlist)if(item.group!=null&&!item.group.isEmpty()&&!AdultGroups.matches(item.group)&&added.add(item.group)){names.add(item.group);ids.add(item.group);}}
  try{JSONArray cats=new JSONArray(app.store.get("language-groups_"+app.favoriteKey()));for(int i=0;i<cats.length();i++){JSONObject c=cats.optJSONObject(i);if(c==null)continue;String name=c.optString("category_name"),id=c.optString("category_id");if(!AdultGroups.matches(name)&&(id.equals(app.liveGroup)||ChannelLanguage.matches("",name,"",app.languageChoice()))){names.add(name);ids.add(id);}}}catch(Exception ignored){}
  groups=new ListView(app);groups.setDividerHeight(0);groups.setSelector(shape(0xff294559,0xff39d9ff));groups.setAdapter(new BaseAdapter(){public int getCount(){return names.size();}public Object getItem(int i){return names.get(i);}public long getItemId(int i){return i;}public View getView(int i,View old,android.view.ViewGroup parent){TextView row=text(names.get(i),12);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(8),dp(4),dp(6),dp(4));row.setSingleLine(true);row.setEllipsize(android.text.TextUtils.TruncateAt.END);row.setMinHeight(dp(29));if(ids.get(i).equals(app.liveGroup)){row.setTextColor(TvStyle.CYAN);row.setBackgroundColor(0xff1c3444);}return row;}});groupColumn.addView(groups,new LayoutParams(-1,0,1));groups.setOnItemClickListener((p,v,i,id)->selectGroup(ids.get(i),names.get(i)));groups.setOnKeyListener((v,key,e)->{if(key==KeyEvent.KEYCODE_DPAD_RIGHT&&e.getAction()==KeyEvent.ACTION_DOWN){gridFocus();return true;}if(key==KeyEvent.KEYCODE_DPAD_LEFT&&e.getAction()==KeyEvent.ACTION_DOWN){navigation.getChildAt(0).requestFocus();return true;}return false;});
  nav(groupColumn,app.languageLabel()+" ▾",()->app.languageSettings(()->app.liveChannels(app.liveSource)),false);
  LinearLayout content=new LinearLayout(app);content.setOrientation(VERTICAL);body.addView(content,new LayoutParams(0,-1,1));
  LinearLayout overview=new LinearLayout(app);overview.setPadding(0,0,0,dp(6));overview.setBackgroundColor(0xff101518);content.addView(overview,new LayoutParams(-1,dp(174)));
