  LinearLayout info=new LinearLayout(app);info.setOrientation(VERTICAL);overview.addView(info,new LayoutParams(0,-1,1));programme=text("Choose a channel",20);programme.setMaxLines(2);programme.setEllipsize(android.text.TextUtils.TruncateAt.END);schedule=text("",11);schedule.setTextColor(TvStyle.CYAN);description=text("",12);description.setMaxLines(3);next=text("",11);next.setMaxLines(1);next.setTextColor(TvStyle.SILVER);technical=text("",10);technical.setMaxLines(5);technical.setTextColor(TvStyle.SILVER);info.addView(programme);info.addView(schedule);info.addView(description,new LayoutParams(-1,0,1));info.addView(next);info.addView(technical);preview.information=message->technical.setText(message);preview.setFocusable(true);preview.setClickable(true);preview.setOnClickListener(v->{if(selectedIndex>=0)tune(model.get(selectedIndex));});preview.setOnFocusChangeListener((v,f)->preview.setBackground(shape(0xff080d16,f?TvStyle.CYAN:0xff263448)));
  LinearLayout tools=new LinearLayout(app);tools.setGravity(Gravity.CENTER_VERTICAL);LayoutParams toolsLp=new LayoutParams(-1,dp(33));toolsLp.topMargin=dp(4);content.addView(tools,toolsLp);
