  for(int i=0;i<channels.length();i++){JSONObject ch=channels.optJSONObject(i);GuideModel.Channel item=new GuideModel.Channel();item.name=ch.optString("name").replaceFirst("(?i)^(US|USA|UK|GB|CA|AU|NZ)[|:]\\s*","");item.logo=ch.optString("stream_icon");item.sourceIndex=i;item.programs=app.lazyPrograms(ch);model.add(item);}
  int initialSelection=app.liveSelection;grid=new ProgramGuideView(app,model,new ProgramGuideView.Host(){public void selected(GuideModel.Channel ch,GuideModel.Program ep){selection(ch,ep);}public void activate(GuideModel.Channel ch,GuideModel.Program ep){watch(ch,ep);}public Bitmap logo(String url,Runnable ready){return image(url,ready);}});
  grid.channelWidth=dp(224);grid.rowHeight=dp(42);grid.span=2*GuideModel.HOUR;grid.optionsAction=()->options();grid.menuAction=()->showGroups();grid.topAction=()->nowTool.requestFocus();grid.row=Math.min(initialSelection,Math.max(0,model.size()-1));listArea=new FrameLayout(app);content.addView(listArea,new LayoutParams(-1,0,1));listArea.addView(grid,new FrameLayout.LayoutParams(-1,-1));catalog=new GuideCatalogPanel(this);catalog.setVisibility(GONE);listArea.addView(catalog,new FrameLayout.LayoutParams(-1,-1));
  status=text("↑↓ Browse   ← Groups   → Schedule   OK Preview / Full screen   Hold OK Options   CH +/− Page   Back Home",10);status.setTextColor(TvStyle.SILVER);status.setPadding(0,dp(7),0,0);content.addView(status);
  app.guideModelCache=model;app.guideSourceCache=channels;app.activeProgramGuide=grid;app.guideModelKey=channels.toString().hashCode()+":"+app.guideRules();restoreBookmark();post(()->{grid.requestFocus();grid.keepVisible();grid.notifySelection();});
